package net.officefloor.hq.app.rollup;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import org.springframework.format.annotation.DateTimeFormat;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

/** The figures of a sheet's descendants, which the screen adds to its own for the consolidated figures. */
@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/descendants")
public class RollupController {

    /**
     * The descendants' figures added up: the number of people (each once), the due-totals and overdue-totals trimmed
     * once over all of them, per grade the due-totals of its people (two decimals), per status the count of claims, and
     * each person with their names and figures, for the screen to work the totals out again with the sheet's own.
     */
    public record ConsolidatedView(int peopleCount, String dueTotal, String overdueTotal,
            Map<String, String> gradeDueTotals, Map<String, Integer> statusCounts, List<MemberView> people) {
        static ConsolidatedView of(RollupService.Consolidated c) {
            Map<String, String> grades = new TreeMap<>();
            c.gradeDueTotals().forEach((g, d) -> grades.put(g, d.toPlainString()));
            Map<String, Integer> statuses = new TreeMap<>();
            c.statusCounts().forEach((s, n) -> statuses.put(s.name(), n));
            return new ConsolidatedView(c.peopleCount(), c.dueTotal().toPlainString(), c.overdueTotal().toPlainString(),
                    grades, statuses, c.members().stream().map(MemberView::of).toList());
        }
    }

    /** One person of the tree: their name and aliases, their due-total (null for n/a) and overdue-total. */
    public record MemberView(List<String> names, String dueTotal, String overdueTotal) {
        static MemberView of(RollupService.Member m) {
            return new MemberView(m.names(), m.dueTotal() == null ? null : m.dueTotal().toPlainString(),
                    m.overdueTotal().toPlainString());
        }
    }

    private final RollupService service;

    public RollupController(RollupService service) {
        this.service = service;
    }

    @GetMapping("/figures")
    public ConsolidatedView figures(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId) {
        return ConsolidatedView.of(service.descendants(sheetId));
    }

    /**
     * The sheet's own figures and its descendants' added up: as the store holds them now, or, given a date, each sheet
     * of the tree as it stood at the end of that day.
     */
    @GetMapping("/consolidated")
    public ConsolidatedView consolidated(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @RequestParam(required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate asOf) {
        return ConsolidatedView.of(asOf == null ? service.consolidated(sheetId) : service.consolidatedAsOf(sheetId, asOf));
    }
}
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.ArrayDeque;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.TreeMap;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.asof.AsOfService;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.PersonSnapshot;
import net.officefloor.hq.app.person.PersonSnapshotRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateChain;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * The figures a sheet shows: each person's claimed and due-total, and the sheet's totals. A change takes a
 * {@link #snapshot} before it and calls {@link #recordChanges} after it, so the audit gets one ROLLUP line per person
 * whose figures (claimed, due-total, overdue-total) moved (in list order) and a TOTALS line when the sheet's totals moved.
 */
@Service
public class RollupService {

    /**
     * One person's figures; a null due-total is n/a. The overdue-total sums their overdue claims' dues. The
     * settled-total sums the figures of their counted settled claims that correct nothing, and the overdue count is how many of their counted
     * claims are overdue (whether or not they have a figure).
     */
    public record Figures(String name, BigDecimal claimed, BigDecimal dueTotal, BigDecimal overdueTotal,
            BigDecimal settledTotal, int overdueCount) {

        /**
         * The person's score: their settled-total divided by 100, minus 5 for each of their overdue claims, rounded
         * half to even to a whole number.
         */
        public BigDecimal score() {
            return settledTotal.subtract(BigDecimal.valueOf(500L * overdueCount))
                    .divide(BigDecimal.valueOf(100)).setScale(0, RoundingMode.HALF_EVEN);
        }
    }

    /** The figures of every person on a sheet, by person id in list order, and the sheet's totals. */
    public record Snapshot(Map<Long, Figures> people, BigDecimal claimedTotal, BigDecimal dueTotal,
            BigDecimal overdueTotal) {
    }

    /**
     * One person of a sheet as the tree counts them: their name and aliases, their due-total (null for n/a) and their
     * overdue-total.
     */
    public record Member(List<String> names, BigDecimal dueTotal, BigDecimal overdueTotal) {
    }

    /**
     * Figures added up over sheets: their people (each person once, those whose names or aliases match being one),
     * the people's due-totals and overdue-totals trimmed once over all of them, per grade the due-totals of the people
     * on it today (retired people left out, n/a skipped), and per status the count of claims in it; with every
     * sheet's people as members, for the totals to be worked out again with more of them.
     */
    public record Consolidated(List<Member> members, Map<String, BigDecimal> gradeDueTotals,
            Map<ClaimStatus, Integer> statusCounts) {

        static Consolidated empty() {
            return new Consolidated(List.of(), new TreeMap<>(), new EnumMap<>(ClaimStatus.class));
        }

        Consolidated plus(Consolidated o) {
            List<Member> all = new ArrayList<>(members);
            all.addAll(o.members);
            Map<String, BigDecimal> grades = new TreeMap<>(gradeDueTotals);
            o.gradeDueTotals.forEach((g, d) -> grades.merge(g, d, BigDecimal::add));
            Map<ClaimStatus, Integer> statuses = new EnumMap<>(ClaimStatus.class);
            statuses.putAll(statusCounts);
            o.statusCounts.forEach((s, n) -> statuses.merge(s, n, Integer::sum));
            return new Consolidated(all, grades, statuses);
        }

        /** The people over the tree, each once: those whose names or aliases match, ignoring case, are one. */
        public int peopleCount() {
            int[] group = new int[members.size()];
            Map<String, Integer> byName = new HashMap<>();
            for (int i = 0; i < members.size(); i++) {
                group[i] = i;
                for (String n : members.get(i).names()) {
                    Integer j = byName.putIfAbsent(n.toLowerCase(Locale.ROOT), i);
                    if (j != null) {
                        group[root(group, i)] = root(group, j);
                    }
                }
            }
            Set<Integer> roots = new HashSet<>();
            for (int i = 0; i < members.size(); i++) {
                roots.add(root(group, i));
            }
            return roots.size();
        }

